import 'dart:typed_data';

/// Container for audio generated by a [VoiceEngine].
class GeneratedAudio {
  const GeneratedAudio({
    required this.durationSeconds,
    required this.sampleRate,
    this.samples,
    this.wavBytes,
    this.audioFilePath,
    this.isFromCache = false,
  });

  /// Raw Float32 audio samples generated by local ONNX runtime (if applicable).
  final Float32List? samples;

  /// Sample rate in Hz (e.g. 24000 Hz).
  final int sampleRate;

  /// Audio duration in seconds.
  final double durationSeconds;

  /// Raw binary WAV bytes returned from cloud TTS or file (if applicable).
  final Uint8List? wavBytes;

  /// Path to a ready-to-play audio file on disk (cached or temp).
  final String? audioFilePath;

  /// Indicates if this chunk was resolved from the local cache.
  final bool isFromCache;

  @override
  String toString() =>
      'GeneratedAudio(duration: ${durationSeconds.toStringAsFixed(2)}s, '
      'sampleRate: $sampleRate, isCached: $isFromCache, '
      'hasFilePath: ${audioFilePath != null}, wavBytes: ${wavBytes?.length ?? 0})';
}

/// Abstract TTS engine interface separating synthesis implementation from playback.
abstract class VoiceEngine {
  /// Synthesizes text into audio.
  ///
  /// Supports both integer [speakerId] (for offline Kokoro/sherpa engines)
  /// and [voice] name, [language] code, and [speed] multiplier.
  Future<GeneratedAudio> synthesize(
    String text, {
    int speakerId = 0,
    String? voice,
    String? language,
    double speed = 1.0,
  });

  /// Number of available speaker styles in the loaded model.
  int get numSpeakers;

  /// Releases resources.
  Future<void> dispose();
}
